/**
 * LoneScale Node - Version 1
 * Discriminator: resource=company, operation=search
 */


interface Credentials {
  loneScaleApi: CredentialReference;
}

/** Search for a company */
export type LoneScaleV1CompanySearchParams = {
  resource: 'company';
  operation: 'search';
/**
 * Company domain to look up. Provide at least one of domain, Linkedin ID, slug or name.
 */
    searchDomain?: string | Expression<string>;
/**
 * Numeric Linkedin company ID (the digits in the linkedin.com/company/ URL)
 */
    searchLinkedinId?: string | Expression<string>;
/**
 * Linkedin universal name / slug (the trailing segment of the company URL)
 */
    searchSlug?: string | Expression<string>;
/**
 * Company name. Best-effort match — prefer domain, Linkedin ID or slug for a deterministic result.
 */
    searchName?: string | Expression<string>;
/**
 * Whether to fall back to on-demand enrichment when no cached match is found, and attach a headcount breakdown when possible
 * @default false
 */
    searchEnrich?: boolean | Expression<boolean>;
};

export type LoneScaleV1CompanySearchNode = {
  type: 'n8n-nodes-base.loneScale';
  version: 1;
  config: NodeConfig<LoneScaleV1CompanySearchParams> & { credentials?: Credentials };
};